solution.code:
#include <stdio.h>

int count_digits(int n) {
    int count = 0;
    do {
        count++;
        n /= 10;
    } while (n > 0);
    return count;
}

int main() {
    printf("%d %d %d\n", count_digits(0), count_digits(7), count_digits(12345));
    return 0;
}
